def _PSVG():
    """The principle, drawn: a Put line, a Call line, the slice at one price, and the total line as their sum."""
    X = lambda s: 60 + (s - 30) * 9.6
    Y = lambda v: 290 - (v + 10) * 260 / 30
    pl = lambda pts: ' '.join(f'{X(a):.1f},{Y(b):.1f}' for a, b in pts)
    t = lambda x, y, s, c='#2a3858', fs=16, w=700, a='middle', ex='': f'<text x="{x:.1f}" y="{y:.1f}" font-size="{fs}" font-weight="{w}" fill="{c}" text-anchor="{a}" {ex}>{s}</text>'
    p = [f'<line x1="{X(30)}" y1="{Y(0):.1f}" x2="{X(80) + 8}" y2="{Y(0):.1f}" stroke="#8a93aa" stroke-width="2"/>',
         f'<line x1="{X(30)}" y1="{Y(-10):.1f}" x2="{X(30)}" y2="{Y(20):.1f}" stroke="#8a93aa" stroke-width="2"/>']
    for s in range(30, 81, 10): p.append(t(X(s), Y(-10) + 22, s, '#5d6a86', 15, 600))
    for v in (-10, 0, 10, 20): p.append(t(X(30) - 10, Y(v) + 5, str(v).replace('-', '−'), '#5d6a86', 15, 600, 'end'))
    p.append(t(556, Y(0) + 18, 'St', '#5d6a86', 15, 800, 'end'))
    p.append(f'<g class="st" data-n="10"><polyline points="{pl([(30, 17), (50, -3), (80, -3)])}" fill="none" stroke="#1f5fd6" stroke-width="4" stroke-dasharray="9 6"/>'
             + t(X(33), Y(17) - 10, 'Put', '#1f5fd6', 17, 800) + f'<circle cx="{X(40)}" cy="{Y(7):.1f}" r="7" fill="#1f5fd6"/>' + t(X(40) - 14, Y(7) - 2, '7', '#1f5fd6', 17, 800, 'end') + '</g>')
    p.append(f'<g class="st" data-n="20"><polyline points="{pl([(30, -2), (60, -2), (80, 18)])}" fill="none" stroke="#e8960c" stroke-width="4" stroke-dasharray="9 6"/>'
             + t(X(77), Y(18) - 10, 'Call', '#c27400', 17, 800) + f'<circle cx="{X(40)}" cy="{Y(-2):.1f}" r="7" fill="#e8960c"/>' + t(X(40) - 12, Y(-2) - 8, '−2', '#c27400', 17, 800, 'end') + '</g>')
    p.append(f'<g class="st" data-n="30"><line x1="{X(40)}" y1="{Y(-10):.1f}" x2="{X(40)}" y2="{Y(20):.1f}" stroke="#6d4df2" stroke-width="2" stroke-dasharray="4 4"/>'
             + f'<circle cx="{X(40)}" cy="{Y(5):.1f}" r="8" fill="#16213a" stroke="#fff" stroke-width="2.5"/>' + t(X(40), 22, '7 + (−2) = 5', '#16213a', 17, 800, 'middle', 'direction="ltr"') + '</g>')
    p.append(f'<g class="st" data-n="40"><polyline points="{pl([(30, 15), (50, -5), (60, -5), (80, 15)])}" fill="none" stroke="#16213a" stroke-width="5.5"/>'
             + t(X(74) + 8, Y(9) + 24, 'Total', '#16213a', 18, 900) + '</g>')
    p.append(f'<g class="st" data-n="50"><circle cx="{X(45)}" cy="{Y(0):.1f}" r="6.5" fill="#fff" stroke="#0b7a70" stroke-width="3"/><circle cx="{X(65)}" cy="{Y(0):.1f}" r="6.5" fill="#fff" stroke="#0b7a70" stroke-width="3"/>'
             + f'<line x1="{X(45)}" y1="{Y(0) + 7:.1f}" x2="{X(45)}" y2="276" stroke="#0b7a70" stroke-width="1.6" stroke-dasharray="3 3"/><line x1="{X(65)}" y1="{Y(0) + 7:.1f}" x2="{X(65)}" y2="276" stroke="#0b7a70" stroke-width="1.6" stroke-dasharray="3 3"/>' + t(X(45), 291, 'איזון: 45', '#0b7a70', 15.5, 800, 'middle', 'direction="rtl"') + t(X(65), 291, 'איזון: 65', '#0b7a70', 15.5, 800, 'middle', 'direction="rtl"')
             + t(X(55), Y(-5) + 22, 'הפסד מרבי: 5', '#c4221f', 15.5, 800, 'middle', 'direction="rtl"') + '</g>')
    return '<svg class="p5-svg" dir="ltr" viewBox="0 0 560 320" role="img" aria-label="קו כולל כסכום של שני קווים">' + ''.join(p) + '</svg>'


